%[text] # Peak Search in FRFT Domain
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] ## Input Signal
% Signal
fs = 100000;
T = 0.25;
t = 0: 1/fs : T - 1/fs;
B = fs/2;
k = B/(2*T);
f0 = 0;
A = 100;

s1 =  A*exp(1i * 2*pi * (f0.*t + 0.5*k.*t.^2)) %[output:1978e0a2]


figure %[output:27b19d7d]
hold on %[output:27b19d7d]
plot(t,real(s1),t,imag(s1)) %[output:27b19d7d]
title("Input Signal") %[output:27b19d7d]
hold off %[output:27b19d7d]

rrc_filter = comm.RaisedCosineTransmitFilter(RolloffFactor=0.3, ...
        Shape='Normal', ...
        FilterSpanInSymbols=10, ...
        OutputSamplesPerSymbol=100);
rrc_filter.Gain = 1/max(coeffs(rrc_filter).Numerator) %[output:9b1f3a45]
rng(1) % Set seed for repeatability
s2_bits = round(rand(1,length(t)/100));
%s2_signal = 2*(s2_bits-0.5); % polar nrz
s2_signal = pskmod(s2_bits,2,pi/4,PlotConstellation=true); %[output:7fe5f947]


s2 = rrc_filter(s2_signal);
s2 = s2(:)';

% Shift to IF and low pass
fc = 20e3;
s2 = s2.*sin(2*pi*20e3*t);
s2 = lowpass(s2,fs/2 - 1e3,fs);

s = 100*s1 + awgn(s2,20);
%[text] Let's have a look at it in frft domain:
p = 0: 1 / 400 : 2;

s_frft = zeros(length(p),length(s));

for i = 1:length(p)
    s_frft(i,:) = frft(s,p(i));
end

s_frft_sqmag = abs(s_frft).^2;

fig = figure();  %[output:8c2977b4]
fig.Position(3:4) = [1000, 500]; %[output:8c2977b4]

subplot(2,1,1) %[output:8c2977b4]
frft_plot = imagesc(p,0:length(s)-1,10*log10(s_frft_sqmag)); %[output:8c2977b4]
xlabel('p') %[output:8c2977b4]
ylabel(" u ") %[output:8c2977b4]
zlabel("|X_\alpha (u)|^2") %[output:8c2977b4]
colormap(gca,hot), colorbar %[output:8c2977b4]
%Place datatip at peak value
[frft_maxval,frft_maxidx] = max(s_frft,[],"all");
frft_maxtip = datatip(frft_plot,'DataIndex',frft_maxidx,'Location','southwest'); %[output:8c2977b4]
frft_plot.DataTipTemplate.DataTipRows(end+1) = dataTipTextRow("Magnitude",s_frft_sqmag); %[output:8c2977b4]

subplot(2,1,2) %[output:8c2977b4]
plot(p,max(10*log10(s_frft_sqmag'))) %[output:8c2977b4]
ylabel("max(|X_\alpha (u)|^2)") %[output:8c2977b4]

hold on; %[output:8c2977b4]
p_opt = p(mod(frft_maxidx,length(p))) %[output:71d38f04]
xline(p_opt, 'r--', 'LineWidth', 1.5); %[output:8c2977b4]
hold off; %[output:8c2977b4]
%%
%[text] ## Algorithm
%[text] Basic Gradient ascent
%[text] For each iteration:
%[text] 1. Calculate FRFT
%[text] 2. Find max(frft(alpha)) \
function peakval = get_frft_pk(sig,p)
    peakval = max(frft(sig,p))
end
%[text] Next iteration:
%[text] 1. Is current \> best? Y -\> current = best \
%[text]  
p_bounds = [0.5 1.5]; %[control:rangeslider:0a7a]{"position":[12,21]}

% One order lower than the difference in bounds.
p_step     = 10^(floor(log10(p_bounds(2)-p_bounds(1)))-1);

p_best     = 0;
p_current  = p_bounds(2);
p_previous = 0;
best_val   = 0;
frft_current = zeros(1,length(s));


max_steps = 50; %[control:editfield:37eb]{"position":[13,15]}


for n = 1:max_steps %[output:group:3058f949]

    if p_current > p_bounds(1)
        frft_current = frft(s,p_current);
        curmax = max(abs(frft_current).^2);

        if curmax > best_val
            best_val = curmax;
            p_best = p_current;
        end
        p_current = p_current - p_step;

    else
        p_bounds(1) = p_best - p_step;
        p_bounds(2) = p_best + p_step;
        p_current = p_bounds(2);
        p_step = p_step*0.1;
    end

    
    % DEBUG
    % p_current_vals(n) = p_current;
    % momentum_vals(n)  = momentum;
    % p_best_vals(n)    = p_best;
    % p_step_vals(n)    = p_step;
     fprintf("%.0f> p_cur: %.2f | p_best: %.2f | best_val: %.4f | p_step: %.4f \n",n,p_current, p_best, best_val, p_step); %[output:370e8a43]
    % 

end %[output:group:3058f949]
%%
%[text] ## Comparing Comms Sig + Isolated
figure %[output:3359056e]
hold on %[output:3359056e]

subplot(3,1,1) %[output:3359056e]
plot((abs(frft(s,p_best)).^2)); %[output:3359056e]
title("Combined Signal") %[output:3359056e]

subplot(3,1,2) %[output:3359056e]
plot((abs(frft(s1,p_best)).^2)); %[output:3359056e]
title("Chirp") %[output:3359056e]

subplot(3,1,3) %[output:3359056e]
plot((abs(frft(s2,p_best)).^2)); %[output:3359056e]
title("Comms Signal") %[output:3359056e]
%%
%[text] ## IFRFT Peak Suppression
s_frft = frft(s,p_best);
s_frft_sqmag = abs(s_frft).^2;
s_frft_sqmag_sdev = std(s_frft_sqmag);

s_frft_cancelled = s_frft .* ~(s_frft_sqmag > 15);
figure %[output:83477318]
hold on %[output:83477318]

subplot(4,1,1) %[output:83477318]
plot((abs(frft(s,p_best)).^2)); %[output:83477318]
title("Combined Signal") %[output:83477318]

subplot(4,1,2) %[output:83477318]
plot((abs(frft(s1,p_best)).^2)); %[output:83477318]
title("Chirp") %[output:83477318]

subplot(4,1,3) %[output:83477318]
plot((abs(frft(s2,p_best)).^2)); %[output:83477318]
title("Comms Signal") %[output:83477318]

subplot(4,1,4) %[output:83477318]
plot((abs(s_frft_cancelled.^2))); %[output:83477318]
title("Cancelled Signal") %[output:83477318]

s_cancelled = frft(s_frft_cancelled,-p_best);


figure %[output:87fd55ca]
hold on %[output:87fd55ca]
subplot(4,1,1) %[output:87fd55ca]
hold on %[output:87fd55ca]
plot(t,real(s1),DisplayName="Real") %[output:87fd55ca]
plot(t,imag(s1),DisplayName="Imaginary") %[output:87fd55ca]
title("Chirp") %[output:87fd55ca]

subplot(4,1,2) %[output:87fd55ca]
hold on %[output:87fd55ca]
plot(t,real(s2),DisplayName="Real") %[output:87fd55ca]
plot(t,imag(s2),DisplayName="Imaginary") %[output:87fd55ca]
title("Comms Signal") %[output:87fd55ca]

subplot(4,1,3) %[output:87fd55ca]
hold on %[output:87fd55ca]
plot(t,real(s),DisplayName="Real") %[output:87fd55ca]
plot(t,imag(s),DisplayName="Imaginary") %[output:87fd55ca]
title("Combined Signal") %[output:87fd55ca]

subplot(4,1,4) %[output:87fd55ca]
hold on %[output:87fd55ca]
plot(t,real(s_cancelled),DisplayName="Real") %[output:87fd55ca]
plot(t,imag(s_cancelled),DisplayName="Imaginary") %[output:87fd55ca]
title("Cancelled Signal") %[output:87fd55ca]
%%
%[text] ## Parameter Estimation
S = sqrt(T/fs) %[output:8ab1e2aa]

est_phi = pi/2 * p_best;
est_f0 = s_frft %[output:01c5e625]

%[text] ## References
%[text] \[1\] X. Chen, J. Guan, S. Yu, and Y. He, 'A novel adaptive filtering for LFM signal in FRFT domain', in IEEE 10th INTERNATIONAL CONFERENCE ON SIGNAL PROCESSING PROCEEDINGS, Oct. 2010, pp. 239–242. doi: 10.1109/ICOSP.2010.5655204.  
%[text]  

